#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long d;
    cin >> n >> d;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    unordered_map<long long, long long> count;
    long long total = 0;
    for (int i = 0; i < n; i++) {
        long long rem = a[i] % d;
        auto it = count.find((d - rem) % d);
        if (it != count.end()) total += it->second;
        count[rem]++;
    }
    cout << total << "\n";

    return 0;
}

